  // on-goal (flow U3): distinct clusters among first-sample PASS cards whose test varies compute
  u3: new Set(CTX.filter(c => isPass(c) && ['yes', 'partly'].includes(c.plan.compute_tested)).map(c => CLUSTER[c.pick.key] ?? c.pick.key)).size,
  // on-goal (U4): distinct clusters among first-sample PASS cards the critic scores reshape >= 4 and baseline >= 3
  u4: new Set(CTX.filter(c => isPass(c) && [['reshape', 4], ['baseline', 3]].every(([k, min]) => {
    const s = ((c.critique && c.critique.scores) || []).find(x => x.criterion === k)
    return s && typeof s.value === 'number' && s.value >= min
  })).map(c => CLUSTER[c.pick.key] ?? c.pick.key)).size,
}
const result_md = safe('result', () => render_result({ header_counts, table, frontier, cards, inventory, log: LOG }), header_counts)
// calibration state per card (2026-10-21): a judged card whose cost rests on a load-bearing GUESS or PROXY is
// calibration_required until a measure run resolves each input (ledger kind card_number_resolved); the record carries
// what the measure run needs: the inputs, their measuring phase and its line, the anchor and the predictions
const calibration = CTX.map(c => {
  const ev = c.eval || {}, plan = c.plan || {}
  const required = (ev.uncertain || []).map(u => {
    const line = (ev.lines || []).find(l => l.phase === u.measured_by) || null
    const phase = (plan.phases || []).find(p => p.id === u.measured_by) || null
    return { id: u.id, basis: u.basis, value: u.value, differs_in: u.differs_in || [], measured_by: u.measured_by || null, cum_spend_through_measured_by: u.cum_spend_through_measured_by ?? null, k_budget: u.k_budget ?? null,
      phase: phase && { id: phase.id, what: phase.what, gate: phase.gate || null, stop_rule: phase.stop_rule || null }, line: line && { id: line.id, hours: line.hours, usd: line.usd } }
  })
  const state = c.halted ? 'not_judged' : !(c.decision && c.decision.result === 'PASS') ? 'rejected' : required.length ? 'calibration_required' : 'no_unmeasured_input'
  return { key: c.pick.key, title: c.pick.title, state, plan_usd: ev.planned ?? null, required, resolved: [],
    anchor: plan.anchor || null, predictions: plan.predictions ? { if_lever: plan.predictions.if_lever, if_not: plan.predictions.if_not, noise_rule: plan.predictions.noise_rule, expected: plan.predictions.expected } : null }
})
return { table, cards, inventory, frontier, log: LOG, result_md, price_sheet: SHEET, calibration }

      ? { status: 'SKIPPED', facts: nullFacts(stage) }
      : await run()
    const timeouts = stageReceipts.filter(receipt => receipt.rc === 124 || receipt.timed_out === true)
    if (timeouts.length) {
      result.facts.timed_out = true
      result.facts.budget_s = timeouts.at(-1).budget_s
      result.facts.overrun = timeouts.some(receipt => receipt.overrun === true)
    }
    const v1 = { ...result.v1, wall_s: (performance.now() - started) / 1000 }
    const families = answeringFamilies(journalOffset)
    v1.model_family = families.at(-1) ?? 'none'
    v1.gpu_s = stageReceipts.reduce((sum, receipt) => sum + (nonnegative(receipt.gpu_busy_s) ? receipt.gpu_busy_s : 0), 0)
    v1.usd = box && nonnegative(box.price_usd_h)
      ? stageReceipts.reduce((sum, receipt) => sum + (nonnegative(receipt.wall_s) ? receipt.wall_s : 0), 0) / 3600 * box.price_usd_h : 0
    stageUSD += v1.usd
    if (stageReceipts.length) result.facts.gpu_busy_known = stageReceipts.every(receipt => receipt.gpu_busy_known === true)
    if (stage === 'takeaways') {
      // A down during the run may have completed the allocation since the snapshot.
      try {
        const current = readJSON(boxPath)
        if (current && typeof current === 'object' && (!box || (current.started_utc === box.started_utc
          && current.type === box.type && current.region === box.region && current.price_usd_h === box.price_usd_h))) {
          box = current
          writeFileSync(path.join(C, 'box.json'), JSON.stringify(box) + '\n')
        }
      } catch { /* The initial snapshot remains sufficient for an active allocation. */ }
      result.facts.run_box_usd = result.status === 'SKIPPED' ? null : runBoxUSD(stageUSD)
    }
    const after = agent.usage?.()
    if (before && after && after.calls > before.calls) {
      v1.tokens_in = after.tokens_in - before.tokens_in
      v1.tokens_out = after.tokens_out - before.tokens_out
      result.facts.tokens_known = after.unknown === before.unknown
    }
    mkdirSync(path.join(C, 'stages'), { recursive: true })
    writeFileSync(path.join(C, 'stages', `${stage}.json`), JSON.stringify({ stage, status: result.status,
      ...v1, ...(stage === 'seal' ? { reason_codes: result.reason_codes ?? [] } : {}),
      notes: new Set(families).size > 1 ? ['multiple_model_families'] : [] }) + '\n')
    await exec('python3', ['m5/signatures.py', 'emit', '--dir', S, '--stage', stage, '--status', result.status,
      '--facts', JSON.stringify(result.facts), '--v1', JSON.stringify(v1)])
    stages.push({ stage, status: result.status })
    log(`${stage}: ${result.status}`)
    if (!stopped_at && (result.status !== 'PASS' || result.facts.outcome === 'no_feasible_method'
      || (stage === 'reproduce' && (Object.hasOwn(input, 'units_check') || Object.hasOwn(input, 'units_probe'))))) stopped_at = stage
  }
  await exec('python3', ['m5/operator_takeaway.py', S, '--raid', raid])
  return { stages, stopped_at }
})()

